import React from 'react';
import { Box, Button, TextField, Typography } from '@mui/material';

const CategoryFilter = ({ categories, categoryFilter, onCategoryChange, searchQuery, onSearchChange, priceRange, onPriceChange }) => {
  return (
    <Box sx={{ mb: 3 }}>
      <Typography variant="h6" gutterBottom>Фильтр по категориям</Typography>

      <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
        {categories.map((category) => (
          <Button
            key={category}
            variant={categoryFilter === category ? 'contained' : 'outlined'}
            onClick={() => onCategoryChange({ target: { value: category }})} 
          >
            {category}
          </Button>
        ))}
      </Box>

      <TextField
        label="Поиск по названию"
        value={searchQuery}
        onChange={onSearchChange}
        fullWidth
        margin="normal"
      />

      <TextField
        label="Цена до"
        type="number"
        value={priceRange}
        onChange={onPriceChange}
        fullWidth
        margin="normal"
      />
    </Box>
  );
};

export default CategoryFilter;
