import React, { useState } from 'react';
import { TextField, Button, MenuItem, Box, Paper, Typography } from '@mui/material';
import axios from 'axios';

const AddProductForm = ({ onProductAdded }) => {
  const [formData, setFormData] = useState({
    name: '',
    price: '',
    description: '',
    image: '',
    category: ''
  });

  const handleChange = (e) => {
    setFormData({...formData, [e.target.name]: e.target.value});
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post('https://67d58416d2c7857431f0a3e7.mockapi.io/market', formData);
      onProductAdded(); // вызываем колбэк для обновления списка
      setFormData({ name: '', price: '', description: '', image: '', category: '' }); // очищаем форму
    } catch (error) {
      console.error("Ошибка при добавлении товара:", error);
    }
  };

  return (
    <Paper elevation={3} sx={{ padding: 3, marginBottom: 4 }}>
      <Typography variant="h6" sx={{ marginBottom: 2 }}>
        Добавить новый товар
      </Typography>
      <form onSubmit={handleSubmit}>
        <Box display="flex" flexDirection="column" gap={2}>
          <TextField name="name" label="Название" value={formData.name} onChange={handleChange} required />
          <TextField name="price" label="Цена" type="number" value={formData.price} onChange={handleChange} required />
          <TextField name="description" label="Описание" value={formData.description} onChange={handleChange} multiline rows={2} />
          <TextField name="image" label="URL изображения" value={formData.image} onChange={handleChange} required />
          <TextField name="category" select label="Категория" value={formData.category} onChange={handleChange} required>
            {['Ноутбуки', 'Телефоны', 'Наушники', 'Компьютеры', 'Мониторы'].map((cat) => (
              <MenuItem key={cat} value={cat}>{cat}</MenuItem>
            ))}
          </TextField>
          <Button type="submit" variant="contained">Добавить</Button>
        </Box>
      </form>
    </Paper>
  );
};

export default AddProductForm;
