import React from 'react';
import { useTheme } from '@mui/material/styles';
import './ContactForm.css';

const ContactForm = () => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  return (
    <div className={`contact-container ${isDark ? 'dark' : 'light'}`}>
      <h2 style={{textAlign:"center",fontSize:40}}>Связаться с нами</h2>
      <p className="contact-subtext">Чем можем помочь?</p>

      <form
        action="https://formspree.io/f/xqapjydp"
        method="POST"
        className="contact-form"
      >
        <label>
          Имя
          <input type="text" name="name" placeholder="Ваше имя" required />
        </label>

        <label>
          Email
          <input type="email" name="email" placeholder="example@mail.com" required />
        </label>

        <label>
          Сообщение
          <textarea name="message" placeholder="Введите ваше сообщение..." rows="5" required></textarea>
        </label>

        <button type="submit">Отправить сообщение</button>
      </form>
    </div>
  );
};

export default ContactForm;
